solutions.naive:
class Solution:
    def equalSubstring(self, s: str, t: str, maxCost: int) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                cost = 0
                for p in range(i, j + 1):
                    cost += abs(ord(s[p]) - ord(t[p]))
                if cost <= maxCost:
                    ans = max(ans, j - i + 1)
        return ans

